-- Spec 25 · Tập luyện: chương trình Có Handicap (8 tuần, mục tiêu có Handicap Index) và Break 100 (12 tuần).
-- Dữ liệu: docs/spec/data/hcp54-b100.json (sinh từ build_hcp54_b100.py). Chỉ tiêu là chỉ tiêu tạm, chỉnh trong admin.
-- Chọn chương trình theo mục tiêu: 54 → Có Handicap; 25–53.9 → Break 100; 18–24.9 → Break 90 (thu hẹp từ 18 trở lên).
insert into public.training_programs (code, name_vi, name_en, kind, audience, target_hcp_min, target_hcp_max, weeks, days_per_week, summary_vi, summary_en, sort_order) values
  ('hcp54', 'Có Handicap', 'Get a Handicap', 'break', 'adult', 54, 54, 8, 3,
   'Giáo án 8 tuần cho người chưa có handicap: kỹ năng tối thiểu, luật, phép lịch sự, nhịp chơi, rồi nộp điểm để có Handicap Index',
   '8-week plan for golfers without a handicap: minimum skills, rules, etiquette and pace of play, then post scores for a Handicap Index', -2),
  ('b100', 'Break 100', 'Break 100', 'break', 'adult', 25, 53.9, 12, 3,
   'Giáo án 12 tuần cho mục tiêu handicap từ 25 đến 53.9: tránh điểm lớn, lên green và tối đa 2 putt',
   '12-week plan for a target handicap of 25 to 53.9: avoid big numbers, reach the green and two-putt', 0)
on conflict (code) do nothing;

update public.training_programs
set target_hcp_max = 24.9, summary_vi = 'Giáo án 12 tuần cho mục tiêu handicap từ 18 đến 24.9', summary_en = '12-week plan for a target handicap of 18 to 24.9'
where code = 'b90' and target_hcp_max is null;

do $$
declare
  d jsonb := $json${"hcp54":[{"w":1,"d":0,"s":[{"a":"putt","h":"Cầm gậy putt và tư thế","m":25,"it":[["p","Khởi động 10 phút trước khi tập: xoay vai, xoay hông, giãn đùi sau, 10 lần swing nhẹ không bóng."],["b","Đặt gậy sắt dưới đất làm đường thẳng, 5 phút putt dọc theo gậy (không cần lỗ)"],["b","Vào 15 bóng từ 2 ft"],["b","Vào 15 bóng từ 3 ft"]]},{"a":"chip","h":"Chip từ mép green","m":20,"it":[["b","20 chip từ mép green bằng gậy sắt 9, đếm số bóng lên green"],["b","10 chip nhắm khu vực 3 bước trước lỗ"]]},{"a":"fir","h":"Swing nửa không bóng","m":25,"it":[["b","20 lần swing nửa không bóng với gậy sắt 7, giữ thăng bằng khi kết thúc"],["b","10 bóng swing nửa với gậy sắt 7, bóng đặt trên tee"],["p","Luật và phép lịch sự tuần này: An toàn: đứng sau và chéo người đang đánh, không đứng trước mặt; chỉ swing khi xung quanh trống; thứ tự đánh: người xa lỗ đánh trước."]]}]},{"w":2,"d":0,"s":[{"a":"putt","h":"Putt ngắn và đều tay","m":25,"it":[["p","Khởi động 10 phút trước khi tập: xoay vai, xoay hông, giãn đùi sau, 10 lần swing nhẹ không bóng."],["b","5 phút putt dọc theo gậy sắt đặt dưới đất"],["b","Vào 20 bóng từ 3 ft"],["b","10 putt từ 10 ft, đếm số bóng dừng trong 3 ft"]]},{"a":"chip","h":"Chip lên green","m":20,"it":[["b","20 chip từ mép green tới lỗ gần (10 ft), đếm số bóng lên green"],["b","20 chip tới lỗ xa (25 ft), đếm số bóng lên green"]]},{"a":"fir","h":"Sắt 7 swing nửa có bóng","m":25,"it":[["b","15 lần swing nửa không bóng với sắt 7"],["b","20 bóng swing nửa với sắt 7, bóng đặt trên tee; đếm số bóng bay lên, không top, không chunk"],["p","Luật và phép lịch sự tuần này: Chăm sóc sân: sửa vết bóng rơi trên green, lấp hoặc đặt lại divot, cào bunker sau khi đánh."]]}]},{"w":3,"d":0,"s":[{"a":"putt","h":"Putt ngắn và putt xa","m":25,"it":[["p","Khởi động 10 phút trước khi tập: xoay vai, xoay hông, giãn đùi sau, 10 lần swing nhẹ không bóng."],["b","Vào 20 bóng từ 3 ft"],["b","10 putt từ 15 ft, đếm số bóng dừng trong 6 ft"]]},{"a":"chip","h":"Pitch 20–50 yd","m":20,"i